use std::fs

fn all_digits(s: string) -> bool {
    if s.len() == 0 {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn best_action(list: Vec<string>) -> string {
    let mut best = ""
    let mut bc = 0
    for a in list {
        let mut n = 0
        for b in list {
            if a == b {
                n += 1
            }
        }
        if n > bc || (n == bc && a < best) {
            bc = n
            best = a.to_string()
        }
    }
    best
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut bad = 0
    let mut users: Vec<string> = []
    let mut counts: Vec<int> = []
    let mut totals: Vec<int> = []
    let mut acts: Vec<Vec<string>> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            bad += 1
            continue
        }
        let secs: int = parts[2].parse::<int>().unwrap_or(0)
        let mut idx: int = -1
        let mut i: int = 0
        while i < users.len() as int {
            if users[i as usize] == parts[0] {
                idx = i
            }
            i += 1
        }
        if idx < 0 {
            users.push(parts[0].to_string())
            counts.push(0)
            totals.push(0)
            acts.push([])
            idx = users.len() as int - 1
        }
        let k = idx as usize
        counts[k] = counts[k] + 1
        totals[k] = totals[k] + secs
        acts[k].push(parts[1].to_string())
    }
    let n = users.len()
    let mut order: Vec<int> = []
    let mut j = 0
    while j < n {
        order.push(j as int)
        j += 1
    }
    let mut a = 0
    while a < n {
        let mut b = 0
        while b + 1 < n - a {
            let x = order[b] as usize
            let y = order[b + 1] as usize
            let mut swap = false
            if totals[x] < totals[y] {
                swap = true
            } else if totals[x] == totals[y] && users[x] > users[y] {
                swap = true
            }
            if swap {
                order[b] = y as int
                order[b + 1] = x as int
            }
            b += 1
        }
        a += 1
    }
    for o in order {
        let k = o as usize
        println("${users[k]} ${counts[k]} ${totals[k]} ${best_action(acts[k])}")
    }
    println("malformed: ${bad}")
}

